create or replace TABLE LDL_DATA_PRODUCTION.ETL.T_FACT_FRAUD_DETECTION_BY_CASH_REGISTER_EVENT_AGG cluster by (BUS_DT)(
	CASH_REGISTER_EVENT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related cash register event. Depending on the scenario, it references a retail event, a price lookup event or a technical cash register event.',
	CASH_REGISTER_EVENT_NR VARCHAR(20) NOT NULL COMMENT 'The sequence number of the cash register transaction. It is unique to the cash register, but might be re-cycled after some time.',
	EVENT_START_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when the cash register event started.',
	BUS_DT DATE NOT NULL COMMENT 'The business date on which the cash register event is counted.',
	CASH_REGISTER_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the cash register which has created this transaction.',
	CASH_REGISTER_NR VARCHAR(20) NOT NULL COMMENT 'The identifier (natural key) for the cash register which has created this transaction.',
	STORE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the store where the related cash register event happened.',
	CASHIER_HASH VARCHAR(32) NOT NULL COMMENT 'The encrypted number of the cashier. (The hash is unique for a given store and a day.)',
	TXN_NET_VAL NUMBER(38,5) NOT NULL COMMENT 'The total net amount of the cash register transaction. (amount in the currency defined by the currency code)',
	TXN_GROSS_VAL NUMBER(38,5) NOT NULL COMMENT 'The total gross amount of the cash register transaction. (amount in the currency defined by the currency code)',
	CANCEL_IN_FAVOUR_GROSS_VAL NUMBER(38,5) COMMENT 'The total gross amount of those lines in this retail event, which have been cancelled and which qualify as the fraud scenario of friendly cancellations.',
	CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency, according to ISO 4217.',
	CANCEL_IN_FAVOUR_LINE_CNT NUMBER(38,0) COMMENT 'The number of those lines in this retail event which have been cancelled and which qualify as the fraud scenario of friendly cancellations.',
	CANCEL_LAST_POS_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the last position in this retail event was cancelled.',
	CANCEL_LAST_POS_ALCOHOL_TOBACCO_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the last position in this retail event was for an alcohol or tobacco product and if this position was cancelled. This flag is a specialization of the scenario expressed by the cancel_last_pos_fg.',
	CANCEL_LAST_POS_EXACT_PAYM_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the last position in this retail event was cancelled and if the customer paid with the exact amount, so that no change was given. This flag is a specialization of the scenario expressed by the cancel_last_pos_fg.',
	CANCEL_LAST_POS_AFTER_SUBTOTAL_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the last position in this retail event was cancelled after a subtotal amount was shown. This flag is a specialization of the scenario expressed by the cancel_last_pos_fg.',
	CANCEL_LAST_POS_HIGHEST_POS_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the last position in this retail event was cancelled and if this position was the one with the highest gross amount on the entire receipt.',
	CANCEL_LAST_POS_OUTSIDE_OPENING_HR_FG BOOLEAN COMMENT 'An indicator showing, if the last position in this retail event was cancelled and if the receipt was created outside the official opening hours of the store.',
	CANCEL_LAST_AND_OTHER_POS_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the last several positions in this retail event were cancelled, including the last position.',
	CANCEL_IN_FAVOUR_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations. (The cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.)',
	CANCEL_IN_FAVOUR_ALCOHOL_TOBACCO_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event contained at least one alcohol or tobacco product and if it classifies as the fraud scenario of a friendly cancellation. (The cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt .) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	CANCEL_IN_FAVOUR_EXACT_PAYM_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and if the customer paid with the exact amount, so that no change was given. (A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	CANCEL_IN_FAVOUR_AFTER_SUBTOTAL_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and if the cancellation happened after a subtotal amount was shown. (A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	CANCEL_IN_FAVOUR_OUTSIDE_OPENING_HR_FG BOOLEAN COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and if the transaction happened outside the regular opening hours of the store. (A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	CANCEL_IN_FAVOUR_MANUAL_DISCOUNT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and if the retail event included a discount which was manually applied. (A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	CANCEL_IN_FAVOUR_WITHOUT_AUTH_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and if the cancellation did not require an authorization. (A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	CANCEL_IN_FAVOUR_HIGHEST_POS_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and if the cancellation was for the position with the highest amount on the receipt. (A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	RETURN_AT_HIGHER_THAN_SALES_PRICE_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return line for a product that was returned at a higher price than it was bought.',
	RETURN_AT_HIGHER_THAN_OFFICIAL_PRICE_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return line for a product that was returned without the original receipt and at a price that was higher than its (maximum) official sales price.',
	RETURN_SAME_PROD_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return line for a product  which has already been returned a at least once in the same week and at the same cashier. Textiles (sub item groups 100, 101, 102, 105 and 106)  are not considered in this scenario.',
	RETURN_MULT_PROD_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained returns of at least two products which have all been sold on the same original receipt.',
	RETURN_MULT_PROD_FULL_QTY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained returns of at least two products which have all been sold on the same original receipt and then all quantities of all products are returned in the same return event.',
	RETURN_SAME_RECEIPT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained returns for a receipt that has already been used for returns at least once in the past.',
	RETURN_SAME_RECEIPT_FULL_QTY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained returns for a receipt that has already been used for returns at least once in the past and if all products on this original sales receipt have been returned in their full quantities in this retail event. (The receipt contains more than one item.)',
	RETURN_SAME_RECEIPT_SAME_CASHIER_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained returns for a receipt that has already been used for returns at least once in the past and if these return attemps happened with the same cashier who originally issued the receipt.',
	RETURN_WITHOUT_RECEIPT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return without the original receipt. I.e. there was no receipt number or the receipt number could not be found.',
	RETURN_WITHOUT_RECEIPT_KE_INPUT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return without the original receipt. I.e. there was no receipt number or the receipt number could not be found. The returned product is manually entered (using input method type = KE.',
	RETURN_WITHOUT_RECEIPT_DV_INPUT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return without the original receipt. I.e. there was no receipt number or the receipt number could not be found. The returned product is manually entered (using input method type = DV.',
	RETURN_NOT_ON_RECEIPT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return with an incorrect original receipt. I.e. the receipt number could be found, however the returned item was not present on this receipt.',
	RETURN_QTY_INVALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return of a product with higher quantity than shown on the original receipt.',
	RETURN_WITHOUT_AUTH_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a return that was not authorized. The retail event must also meet all of the following conditions. (1) There is more than one return on the receipt. (2) None of the returned products is on the following receipt. (3) The return amount is not identical to the amount of the following receipt. (4) If the following receipt contains only one product, this must be different from the products on the original receipt.',
	RETURN_SAME_CASHIER_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought at the same cashier.',
	RETURN_SAME_CASHIER_DIFF_DAY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought at the same cashier, but on a different day.',
	RETURN_SAME_CASHIER_AND_DAY_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought on the same day and at the same cashier.',
	RETURN_SAME_CASHIER_AND_DAY_CARD_PAYM_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought on the same day and at the same cashier, and the refund was made to a card of the client.',
	RETURN_SAME_CASHIER_AND_DAY_CASH_PAYM_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought on the same day and at the same cashier, and the refund was made in cash.',
	RETURN_SAME_CASHIER_AND_DAY_WITHOUT_AUTH_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought on the same day and at the same cashier, and the return did not require authorization.',
	RETURN_SAME_CASHIER_AND_DAY_MANUAL_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought on the same day and at the same cashier, and the code of the returned item was entered manually in the system. (Only prod_entry_method_cd = <KE>, by business requirement type <D>, which also represent manual entry, does not count.)',
	RETURN_SAME_CASHIER_AND_DAY_DISPLAY_SEL_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained the return of a product that was bought on the same day and at the same cashier and the product was selected from a list on the display of the cash register. (product entry method LS)',
	DEPOSIT_AND_ONE_PROD_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained a deposit return and exactly one additional sales item.',
	DEPOSIT_ONLY_MANUAL_INPUT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event only contained a deposit return (and no other sales lines) and if this deposit return was manually entered.',
	DEPOSIT_SAME_EAN_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the same deposit receipt was scanned multiple times. (The receipt is identified by its EAN.)',
	PRICE_INFO_MULT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if there were multiple (i.e. at least two) price information events in a row.',
	PRICE_INFO_AND_SMALL_SALE_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if a price information event was followed by a small sales transaction.',
	PRICE_INFO_AND_LOGOFF_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if a price information event was followed by a logoff from the cash register.',
	SUSPEND_AND_ABORT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event was first suspended and subsequently aborted.',
	SUSPEND_AND_LINE_CANCEL_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event was first suspended and some lines were subsequently cancelled.',
	SUSPEND_AND_EXTEND_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event was first suspended and subsequently extended by some more products.',
	SUSPEND_UNRESOLVED_AND_SALE_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event was suspended and has never been resolved. The suspended transaction was followed by a sales transaction.',
	SUSPEND_UNRESOLVED_AND_LOGOFF_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail was suspended and never resolved. The cashier logged off right after suspending the transaction.',
	ABORT_AND_SALE_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event was aborted and if it was followed by a sales transaction.',
	ABORT_AND_LOGOFF_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event was aborted and the cashier logged off right afterwards.',
	SMALL_SALE_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the retail event contained only one product and if the total value is less than a pre-defined threshold (e.g. 20c).',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	CUST_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the customer.',
	CUST_IDENT_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the way how the customer identifies himself in the store, e.g. by his loyalty card.',
	CANCEL_IN_FAVOUR_LIDL_PLUS_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and if the customer used loyalty card, like Lidl Plus. A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.',
	EVENT_END_TMSP TIMESTAMP_TZ(9) COMMENT 'The point in time when the retail event ended.',
	CANCEL_LAST_POS_WITHOUT_AUTH_FG BOOLEAN COMMENT 'An indicator showing, if the last position in this retail event was cancelled and if this cancellation happened without an authorization.',
	CANCEL_LAST_POS_SINGLE_POS_FG BOOLEAN COMMENT 'An indicator showing, if the last position in this retail event was cancelled and the receipt has only one retail line.',
	CANCEL_IN_FAVOUR_SINGLE_POS_FG BOOLEAN COMMENT 'An indicator showing, if this retail event classifies as the fraud scenario of friendly cancellations and the receipt has only one retail line. (A friendly cancellation means that the cashier cancels certain expensive positions on the receipt, so that an accomplice gets them for free. In order to qualify, a minimum number of lines must be cancelled on the receipt.) This flag is a specialization of the scenario expressed by the cancel_in_favour_fg.',
	CANCEL_LAST_POS_GROSS_VAL NUMBER(38,5) COMMENT 'The total gross amount of those lines in this retail event, which have been cancelled as the last n positions on the receipt.',
	CANCEL_LAST_POS_LINE_CNT NUMBER(38,0) COMMENT 'The number of those lines in this retail event which have been cancelled as the last n positions on the receipt.',
	RETURN_MULT_PROD_SAME_CASHIER_FG BOOLEAN COMMENT 'An indicator showing, if the retail event contained returns of at least two products which have all been sold on the same original receipt and the return and the original purchase have been made with the same cashier,',
	DEPOSIT_SAME_EAN_GROSS_VAL NUMBER(38,5) COMMENT 'The total gross amount of those lines which qualify as the fraud scenario of a deposit return with the same EAN (deposit_same_ean_fg). I.e. the same deposit receipt was scanned multiple times. (The receipt is identified by its EAN.) The scenario can span multiple receipts.',
	DEPOSIT_SAME_EAN_LINE_CNT NUMBER(38,0) COMMENT 'The number of those lines which qualify as the fraud scenario of a deposit return with the same EAN (deposit_same_ean_fg). I.e. the same deposit receipt was scanned multiple times. (The receipt is identified by its EAN.) The scenario can span multiple receipts.',
	EVENT_OUTSIDE_EXACT_OPENING_HR_FG BOOLEAN COMMENT 'An indicator showing, if the retail event took place outside the official opening hours of the store. (The exact opening and closing times are taken as criteria. No buffer time is taken into consideration.)',
	RECEIPT_OUTSIDE_OPENING_HR_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	RECEIPT_OUTSIDE_OPENING_HR_CANCEL_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store and if it contained at least one position which was cancelled. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	RECEIPT_OUTSIDE_OPENING_HR_RETURN_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store and if it contained at least one return position. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	RECEIPT_OUTSIDE_OPENING_HR_SUSPEND_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store and if it was suspended. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	RECEIPT_OUTSIDE_OPENING_HR_ABORT_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store and if it was aborted. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	RECEIPT_OUTSIDE_OPENING_HR_DEPOSIT_ONLY_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store and if it contained only deposit lines. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	RECEIPT_OUTSIDE_OPENING_HR_MANUAL_DEPOSIT_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store and if it contained deposits which were manually entered. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	RECEIPT_OUTSIDE_OPENING_HR_MANUAL_DISCOUNT_FG BOOLEAN COMMENT 'An indicator showing, if the receipt was generated outside the official opening hours of the store and if it contained discounts which were manually entered. (A buffer of a few minutes before the opening time and after the closing time is allowed.)',
	DEPOSIT_SAME_VAL_MAN_FG BOOLEAN COMMENT 'An indicator showing, if the retail event contained a manual deposit return and is coupled with a following scanned deposit return',
	DEPOSIT_SAME_VAL_SCAN_FG BOOLEAN COMMENT 'An indicator showing, if the retail event is a scanned deposit return and is coupled with a preceding manual deposit return',
	constraint PK_T_FACT_FRAUD_DETECTION_BY_CASH_REGISTER_EVENT primary key (CASH_REGISTER_EVENT_SID)
);